  const g = c.getContext('2d');
  g.fillStyle = base; g.fillRect(0, 0, 128, 256);
  for (let y = 14; y < 240; y += 30) {
    for (let x = 12; x < 116; x += 28) {
      g.fillStyle = Math.random() < 0.35 ? '#ffe9a8' : '#22303f';
      g.fillRect(x, y, 18, 20);
    }
